INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','noun-clauses','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"noun-clauses","title":"Indirect questions, noun clauses and preparatory it","level":"B2","order":56,"summary":"Use a whole clause as a subject, object or complement, and keep embedded questions in statement order.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Clauses can fill noun-like roles","Polite indirect questions","Whether before an infinitive","Preparatory it"],"rules":[{"title":"Clauses can fill noun-like roles","explanation":"A that-clause can express the content of a belief, statement or fact. It may be the object of a verb or follow a noun or adjective. In many object clauses, that can be omitted, but it helps readers recognise a complex structure.","pattern":"I believe **that she is right**.","commonMistakes":["That does not itself supply a subject and verb; the words after it still need a complete clause."],"examples":["Choose the polite indirect question about the visitor guide. → **Could you tell me why she prepares the visitor guide?**","Choose the polite indirect question about the old portrait. → **Could you tell me why she restores the old portrait?**"],"skill":"form"},{"title":"Polite indirect questions","explanation":"An opening such as Could you tell me can make a question less direct. Inside the embedded question, use statement order. The whole sentence still takes a question mark because the outer clause is a question.","pattern":"Could you tell me **where she works**?","commonMistakes":["Where does she work is direct-question order, not the order required inside this embedded clause."],"examples":["“We have not decided **whether** to prepare the visitor guide today.”","“We have not decided **whether** to restore the old portrait today.”"],"skill":"meaning"},{"title":"Whether before an infinitive","explanation":"Use **whether to + base verb** to discuss a choice or uncertainty about an action. Whether can also introduce alternatives or follow a preposition. If is common in finite yes/no reports but does not normally replace whether before to-infinitives.","pattern":"We discussed **whether to leave**.","commonMistakes":["We discussed if to leave is not the standard pattern."],"examples":["“**It** is important to prepare the visitor guide carefully.”","“**It** is important to restore the old portrait carefully.”"],"skill":"contrast"},{"title":"Preparatory it","explanation":"English often uses **it** as a grammatical subject when a long clause or infinitive is placed later. This can make information easier to process. Compare To check is important with It is important to check. It here does not refer to an object.","pattern":"**It is important to check** the details.","commonMistakes":["Do not omit the grammatical subject in an ordinary English statement: Is important to check is incomplete."],"examples":["Complete the content clause: “We know that she **prepares** the visitor guide every week.”","Complete the content clause: “We know that she **restores** the old portrait every week.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference","dfe-grammar"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"88ab8084-e3ee-5914-af1f-e0c4fffa2013","topicSlug":"noun-clauses","level":"B2","prompt":"Choose the polite indirect question about the visitor guide.","choices":[{"id":"A","text":"Could you tell me why she to prepare the visitor guide?"},{"id":"B","text":"Could you tell me why she prepares the visitor guide?"},{"id":"C","text":"Could you tell me why does she prepare the visitor guide?"},{"id":"D","text":"Could you tell me why she prepare the visitor guide?"}],"answerId":"B","hint":"The outer clause is the question; the inner clause keeps **statement order**.","explanation":"Inside **why she ...**, the subject comes before the verb; does is not retained.","keywords":["indirect-question-order"],"skill":"indirect-question-order","contextKey":"noun-clauses-1","fingerprint":"6bf1a732a28d79495a6b35b20d195df629197ecd453f240daa95b24bdfa6230f","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The outer clause is the question; the inner clause keeps **statement order**.","Inside **why she ...**, the subject comes before the verb; does is not retained.","Choose **Could you tell me why she prepares the visitor guide?**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive cannot serve as the finite predicate after she.","B":"Inside **why she ...**, the subject comes before the verb; does is not retained.","C":"This retains direct-question inversion inside the embedded clause.","D":"The singular third-person subject needs the -s verb in this present-simple clause."}}},{"id":"15c53313-8c98-51fe-ab7c-14a32343b5fc","topicSlug":"noun-clauses","level":"B2","prompt":"“We have not decided ____ to prepare the visitor guide today.”","choices":[{"id":"A","text":"if"},{"id":"B","text":"that"},{"id":"C","text":"what"},{"id":"D","text":"whether"}],"answerId":"D","hint":"Before a **to-infinitive** expressing a yes/no choice, use whether.","explanation":"**Whether to** introduces the decision between doing and not doing the task.","keywords":["whether-infinitive"],"skill":"whether-infinitive","contextKey":"noun-clauses-1","fingerprint":"672766ad74d3f8b30c2012f2054b04427e9a73972d9aff52daafccb3b4ce6434","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Before a **to-infinitive** expressing a yes/no choice, use whether.","**Whether to** introduces the decision between doing and not doing the task.","Choose **whether**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"If does not normally introduce a to-infinitive in this pattern.","B":"That does not introduce this whether-or-not choice before an infinitive.","C":"What to would mean choosing an object, but the task already supplies the object.","D":"**Whether to** introduces the decision between doing and not doing the task."}}},{"id":"197f4247-6aea-5622-a279-84eefbd5d866","topicSlug":"noun-clauses","level":"B2","prompt":"“____ is important to prepare the visitor guide carefully.”","choices":[{"id":"A","text":"It"},{"id":"B","text":"There"},{"id":"C","text":"—"},{"id":"D","text":"They"}],"answerId":"A","hint":"The real content comes in the infinitive; English still needs a **grammatical subject**.","explanation":"Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","keywords":["preparatory-it"],"skill":"preparatory-it","contextKey":"noun-clauses-1","fingerprint":"20d59e0cca091a2fc161438aa162ef3a17ed8651ca539bcad41c064ecb54abd5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The real content comes in the infinitive; English still needs a **grammatical subject**.","Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","Choose **It**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","B":"Existential there does not introduce this adjective + infinitive evaluation.","C":"An ordinary English statement needs a subject here.","D":"They does not agree with is and does not serve as preparatory it."}}},{"id":"173b0425-c226-5784-aef1-32ea2eee9cc6","topicSlug":"noun-clauses","level":"B2","prompt":"Complete the content clause: “We know that she ____ the visitor guide every week.”","choices":[{"id":"A","text":"prepares"},{"id":"B","text":"prepare"},{"id":"C","text":"to prepare"},{"id":"D","text":"been prepared"}],"answerId":"A","hint":"A **that-clause** has its own subject and finite verb.","explanation":"The that-clause is finite, so **she prepares** uses present agreement.","keywords":["finite-that-clause"],"skill":"finite-that-clause","contextKey":"noun-clauses-1","fingerprint":"8805f3bbf40f4b30b4a84dbaaaa013e493ba23e7b80c44ca33ad4b22ef6e118d","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **that-clause** has its own subject and finite verb.","The that-clause is finite, so **she prepares** uses present agreement.","Choose **prepares**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The that-clause is finite, so **she prepares** uses present agreement.","B":"The third-person singular subject requires -s in this affirmative clause.","C":"A to-infinitive is not a finite verb after she.","D":"Been would need an auxiliary and does not fit this active present-simple clause."}}},{"id":"8a177f76-921a-51f0-ae14-767dd3754bb8","topicSlug":"noun-clauses","level":"B2","prompt":"Choose the polite indirect question about the old portrait.","choices":[{"id":"A","text":"Could you tell me why she to restore the old portrait?"},{"id":"B","text":"Could you tell me why she restores the old portrait?"},{"id":"C","text":"Could you tell me why does she restore the old portrait?"},{"id":"D","text":"Could you tell me why she restore the old portrait?"}],"answerId":"B","hint":"The outer clause is the question; the inner clause keeps **statement order**.","explanation":"Inside **why she ...**, the subject comes before the verb; does is not retained.","keywords":["indirect-question-order"],"skill":"indirect-question-order","contextKey":"noun-clauses-2","fingerprint":"a6bdedfd1491d016cb0fda982c68dae8104d05da6a48c6f966690ed812f52236","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The outer clause is the question; the inner clause keeps **statement order**.","Inside **why she ...**, the subject comes before the verb; does is not retained.","Choose **Could you tell me why she restores the old portrait?**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"A to-infinitive cannot serve as the finite predicate after she.","B":"Inside **why she ...**, the subject comes before the verb; does is not retained.","C":"This retains direct-question inversion inside the embedded clause.","D":"The singular third-person subject needs the -s verb in this present-simple clause."}}},{"id":"29fc2e89-38b7-5e05-a857-355b532b2103","topicSlug":"noun-clauses","level":"B2","prompt":"“We have not decided ____ to restore the old portrait today.”","choices":[{"id":"A","text":"what"},{"id":"B","text":"whether"},{"id":"C","text":"if"},{"id":"D","text":"that"}],"answerId":"B","hint":"Before a **to-infinitive** expressing a yes/no choice, use whether.","explanation":"**Whether to** introduces the decision between doing and not doing the task.","keywords":["whether-infinitive"],"skill":"whether-infinitive","contextKey":"noun-clauses-2","fingerprint":"c0d9e7e3b0630447acce1b2b2c189473645dcc58b10f5922cb899fee68392b68","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Before a **to-infinitive** expressing a yes/no choice, use whether.","**Whether to** introduces the decision between doing and not doing the task.","Choose **whether**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"What to would mean choosing an object, but the task already supplies the object.","B":"**Whether to** introduces the decision between doing and not doing the task.","C":"If does not normally introduce a to-infinitive in this pattern.","D":"That does not introduce this whether-or-not choice before an infinitive."}}},{"id":"e49af599-7839-54e1-a3fb-e25ad72c950a","topicSlug":"noun-clauses","level":"B2","prompt":"“____ is important to restore the old portrait carefully.”","choices":[{"id":"A","text":"It"},{"id":"B","text":"There"},{"id":"C","text":"—"},{"id":"D","text":"They"}],"answerId":"A","hint":"The real content comes in the infinitive; English still needs a **grammatical subject**.","explanation":"Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","keywords":["preparatory-it"],"skill":"preparatory-it","contextKey":"noun-clauses-2","fingerprint":"0289cd19a4f396fa2f78a1389add822c762296988eaa52e4af4094b3ee96c5b5","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["The real content comes in the infinitive; English still needs a **grammatical subject**.","Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","Choose **It**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Preparatory **it** fills the subject position, with the important action expressed later by the infinitive.","B":"Existential there does not introduce this adjective + infinitive evaluation.","C":"An ordinary English statement needs a subject here.","D":"They does not agree with is and does not serve as preparatory it."}}},{"id":"87249848-0a96-52b3-a25e-22da322f76ef","topicSlug":"noun-clauses","level":"B2","prompt":"Complete the content clause: “We know that she ____ the old portrait every week.”","choices":[{"id":"A","text":"restores"},{"id":"B","text":"restore"},{"id":"C","text":"to restore"},{"id":"D","text":"been restored"}],"answerId":"A","hint":"A **that-clause** has its own subject and finite verb.","explanation":"The that-clause is finite, so **she restores** uses present agreement.","keywords":["finite-that-clause"],"skill":"finite-that-clause","contextKey":"noun-clauses-2","fingerprint":"70ced01b6344ed5a4d602db37c4b097926cb82a1fe1e7e214a6cf6753216548b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-questions-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A **that-clause** has its own subject and finite verb.","The that-clause is finite, so **she restores** uses present agreement.","Choose **restores**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The that-clause is finite, so **she restores** uses present agreement.","B":"The third-person singular subject requires -s in this affirmative clause.","C":"A to-infinitive is not a finite verb after she.","D":"Been would need an auxiliary and does not fit this active present-simple clause."}}},{"id":"f17183b8-f591-57a7-af4e-f255566357c5","topicSlug":"noun-clauses","level":"B2","prompt":"Choose the polite indirect question about the garden fence.","choices":[{"id":"A","text":"Could you tell me why she mea